// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, DEFAULT_RATIO, DEFAULTS, FOREGROUND, STOPS, VERDICTS } from './script'

const SQUARE = { w: 176, h: 120 }
const PASS = {
  color: '#6ee7b7',
  backgroundColor: 'rgba(52,211,153,0.08)',
  borderColor: 'rgba(52,211,153,0.45)',
}
const FAIL = {
  color: '#fda4af',
  backgroundColor: 'rgba(251,113,133,0.08)',
  borderColor: 'rgba(251,113,133,0.45)',
}
const handle = (index: number) => ({
  x: Math.round((STOPS[index].hsv.s / 100) * SQUARE.w),
  y: Math.round((1 - STOPS[index].hsv.v / 100) * SQUARE.h),
})

const build: Build = ({
  tl,
  q,
  step,
  final,
  move,
  moveTo,
  click,
  type,
  count,
  pos,
  wait,
  cursorOut,
}) => {
  const flip = (verdictIndex: number, pass: boolean, at?: string) => {
    const card = q(`verdict-${verdictIndex}`)
    tl.to(card, { rotationX: 90, duration: 0.14, ease: 'power2.in' }, at)
    tl.set(q(`badge-${verdictIndex}`), { text: pass ? 'PASS' : 'FAIL' })
    tl.set(card, { ...(pass ? PASS : FAIL) })
    tl.to(card, { rotationX: 0, duration: 0.22, ease: 'back.out(2)' })
  }
  const verdicts = (index: number, at?: string) => {
    const changed = VERDICTS.map(({ key }, verdictIndex) => ({
      verdictIndex,
      pass: STOPS[index][key],
      before: index === 0 ? null : STOPS[index - 1][key],
    })).filter((item) => item.before !== item.pass)
    changed.forEach((item, order) => flip(item.verdictIndex, item.pass, order === 0 ? at : '>-0.1'))
  }
  const drag = (index: number) => {
    const point = handle(index)
    const square = pos('square', 0, 0)
    tl.to(q('handle'), { x: point.x, y: point.y, duration: 0.8, ease: 'power2.inOut' })
    moveTo(square.x + point.x, square.y + point.y, { at: '<', duration: 0.8 })
    tl.to(
      [q('bg-swatch'), q('bg-chip'), q('preview')],
      { backgroundColor: STOPS[index].hex, duration: 0.8, ease: 'power2.inOut' },
      '<',
    )
    tl.to(
      q('bg-text'),
      { text: { value: STOPS[index].hex, delimiter: '' }, duration: 0.8, ease: 'none' },
      '<',
    )
    count('ratio', STOPS[index].ratio, {
      from: STOPS[index - 1].ratio,
      at: '<',
      duration: 0.8,
      decimals: 2,
      suffix: ':1',
    })
    verdicts(index, '>-0.2')
  }

  step(0)
  move('fg-input', { ax: 0.3, at: 0.2 })
  click('fg-input')
  tl.to(q('fg-text'), { text: '', duration: 0.15 }, '<')
  type('fg-text', FOREGROUND, { speed: 0.05 })
  tl.to(q('fg-swatch'), { backgroundColor: FOREGROUND, duration: 0.2 }, '<')
  move('bg-input', { ax: 0.3 })
  click('bg-input')
  tl.to(q('bg-text'), { text: '', duration: 0.15 }, '<')
  type('bg-text', STOPS[0].hex, { speed: 0.05 })
  tl.to(
    [q('bg-swatch'), q('bg-chip'), q('preview')],
    { backgroundColor: STOPS[0].hex, duration: 0.3 },
    '<0.2',
  )
  tl.to(q('preview'), { color: FOREGROUND, duration: 0.3 }, '<')
  count('ratio', STOPS[0].ratio, {
    from: DEFAULT_RATIO,
    at: '<',
    duration: 0.5,
    decimals: 2,
    suffix: ':1',
  })
  verdicts(0, '<0.2')

  step(1, '+=0.4')
  move('bg-chip')
  click('bg-chip')
  tl.fromTo(
    q('picker'),
    { opacity: 0, scale: 0.92, y: -6 },
    { opacity: 1, scale: 1, y: 0, duration: 0.3, ease: 'back.out(2)' },
    '<',
  )
  const start = handle(0)
  const square = pos('square', 0, 0)
  tl.set(q('handle'), { x: start.x, y: start.y }, '<')
  moveTo(square.x + start.x, square.y + start.y, { at: '+=0.1' })
  drag(1)
  drag(2)

  step(2, '+=0.4')
  drag(3)
  tl.to(q('picker'), { opacity: 0, scale: 0.95, duration: 0.25 }, '+=0.3')

  step(3, '+=0.3')
  move('copy')
  click('copy')
  tl.to(q('copy'), { color: '#f472b6', duration: 0.15 }, '<')
  tl.fromTo(q('copied'), { opacity: 0, x: -4 }, { opacity: 1, x: 0, duration: 0.25 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function ColorRow({
  name,
  label,
  value,
  hex,
}: {
  name: 'fg' | 'bg'
  label: string
  value: string
  hex: string
}) {
  return (
    <div className="flex items-center gap-1.5">
      <span
        data-d={`${name}-swatch`}
        className="size-6 shrink-0 rounded border border-white/15"
        style={{ backgroundColor: hex }}
      />
      <span
        data-d={`${name}-input`}
        className="flex h-7 flex-1 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[10px] text-ink"
        aria-label={label}
      >
        <span data-d={`${name}-text`}>{value}</span>
      </span>
      <span
        data-d={`${name}-chip`}
        className="size-7 shrink-0 rounded-md border border-line-strong"
        style={{ backgroundColor: hex }}
      />
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Contrast Checker flipping WCAG AA and AAA verdicts as a button background is dragged darker"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full gap-3">
          <div className="flex w-[250px] shrink-0 flex-col gap-1.5">
            <ColorRow
              name="fg"
              label="Foreground color"
              value={DEFAULTS.foreground}
              hex={DEFAULTS.foreground}
            />
            <ColorRow
              name="bg"
              label="Background color"
              value={DEFAULTS.background}
              hex={DEFAULTS.background}
            />
            <div
              data-d="preview"
              className="rounded-md border border-line py-2 text-center"
              style={{ backgroundColor: DEFAULTS.background, color: DEFAULTS.foreground }}
            >
              <p className="text-[10px] font-medium">Normal text preview</p>
              <p className="text-[14px] font-bold">Large text</p>
            </div>
            <div className="flex items-center justify-between rounded-md border border-line bg-white/[0.03] px-2 py-1.5">
              <span className="text-[10px] font-medium text-ink-soft">Contrast ratio</span>
              <span className="flex items-center gap-1.5">
                <span data-d="copied" className="text-[9px] text-[var(--accent)] opacity-0">
                  Copied
                </span>
                <code
                  data-d="ratio"
                  className="font-mono text-[12px] font-semibold tabular-nums text-ink"
                >
                  {DEFAULT_RATIO}:1
                </code>
                <span data-d="copy" className="text-muted">
                  <CopyIcon className="size-3" />
                </span>
              </span>
            </div>
            <div className="grid grid-cols-2 gap-1.5 [perspective:400px]">
              {VERDICTS.map((verdict, index) => (
                <div
                  key={verdict.key}
                  data-d={`verdict-${index}`}
                  className="rounded-md border py-1 text-center"
                  style={PASS}
                >
                  <span
                    data-d={`badge-${index}`}
                    className="rounded border border-current px-1.5 text-[8.5px] font-semibold"
                  >
                    PASS
                  </span>
                  <p className="mt-0.5 text-[9px] text-muted">{verdict.label}</p>
                </div>
              ))}
            </div>
          </div>
          <div className="relative min-w-0 flex-1 pt-10">
            <div
              data-d="picker"
              className="w-fit rounded-lg border border-line-strong bg-elevated p-2 opacity-0 shadow-2xl"
            >
              <div
                data-d="square"
                className="relative rounded"
                style={{
                  width: SQUARE.w,
                  height: SQUARE.h,
                  background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, hsl(${STOPS[0].hsv.h}, 100%, 50%))`,
                }}
              >
                <span
                  data-d="handle"
                  className="absolute -left-1.5 -top-1.5 size-3 rounded-full border-2 border-white shadow-[0_0_0_1px_rgba(0,0,0,0.4)]"
                />
              </div>
              <div
                className="mt-2 h-2.5 rounded-full"
                style={{
                  background: 'linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)',
                }}
              />
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
